from pathlib import Path
import unittest
import oxidize_pdf as pdf
ROOT = Path('/tmp/oxidize-issue-627/oxidize-pdf-core/tests/fixtures/signatures')
class BindingSmoke(unittest.TestCase):
    def test_unsigned_document(self):
        doc=pdf.Document(); doc.add_page(pdf.Page(612,792))
        self.assertEqual(pdf.verify_pdf_signatures(bytes(doc.save_to_bytes())), [])
    def test_certificate_rejects_untrusted_root(self):
        for store in [pdf.TrustStore.empty(),pdf.TrustStore.mozilla_roots()]:
            result=pdf.validate_pdf_certificate((ROOT/'cms_root.der').read_bytes(),store)
            self.assertFalse(result.is_trusted)
            self.assertFalse(result.is_valid())
    def test_malformed_certificate_rejected(self):
        with self.assertRaises(Exception):
            pdf.validate_pdf_certificate(b'bad DER',pdf.TrustStore.empty())
    def test_external_cms_parses(self):
        for name in ['cms_rsa_sha256.der','cms_ecdsa_sha256.der']:
            self.assertIsNotNone(pdf.parse_pkcs7_signature((ROOT/name).read_bytes()))
if __name__=='__main__': unittest.main()
